// Destruct before captured logs/counters, including failure unwinds. A detached
// Home may already have replaced Practice, so the guard owns no raw lifetime.
struct CallbackReset {
 juce::Component::SafePointer<desktop::PracticeView> view;
 explicit CallbackReset(desktop::PracticeView& v):view(&v){}
 ~CallbackReset(){if(view){view->onTempoProgress={};view->onTempoReply={};view->onProgress={};view->onScheduledFact={};view->onTabProgress={};view->onPracticeCommand={};}}
};
const TV& tf(const TV& v,const char* key){return v.object().at(key);}
TV tn(std::uint64_t x){return TV::fromInteger(static_cast<std::int64_t>(x));}
